adcs_vec3_t h, err;
adcs_status_t st;
double norm, energy;
unint32 i;
int enable;
int valid = 1;

/* 入口先给输出赋值，保证每条返回路径都写到 */
wm_output.mode = wm_state.mode;
wm_output.good = wm_state.good;
wm_output.momentum = (adcs_vec3_t){0, 0, 0};
wm_output.error = (adcs_vec3_t){0, 0, 0};
wm_output.error_norm = 0.0;
wm_output.error_energy = 0.0;

enable = wm_input.enable;

/* disable resets：enable == 0 直接复位状态 */
if (enable == 0) {
    wm_state.mode = WM_ACTIVE;
    wm_state.good = 0U;
    wm_output.mode = WM_ACTIVE;
    wm_output.good = 0U;
    return;
}

/* 校验：指针、count、config、wheel 维度与有限性 */
if ((wm_input.wheels == NULL) || (wm_input.count != 4U)) {
    valid = 0;
}
if (valid) {
    if ((!isfinite(wm_config.target.x)) || (!isfinite(wm_config.target.y)) ||
        (!isfinite(wm_config.target.z))) {
        valid = 0;
    }
}
if (valid) {
    if ((!isfinite(wm_config.stop)) || (wm_config.stop < 0.0) || (!isfinite(wm_config.restart)) ||
        (wm_config.restart <= wm_config.stop) || (wm_config.required < 1U) ||
        (wm_config.required > 20U)) {
        valid = 0;
    }
}
if (valid) {
    for (i = 0U; i < wm_input.count; i++) {
        if ((!isfinite(wm_input.wheels[i].axis_body.x)) ||
            (!isfinite(wm_input.wheels[i].axis_body.y)) ||
            (!isfinite(wm_input.wheels[i].axis_body.z)) ||
            (!isfinite(wm_input.wheels[i].inertia_kg_m2)) ||
            (!isfinite(wm_input.wheels[i].speed_rad_s))) {
            valid = 0;
            break;
        }
    }
}

if (!valid) {
    wm_state.mode = WM_FAULT;
    wm_state.good = 0U;
    wm_output.mode = WM_FAULT;
    wm_output.good = 0U;
    return;
}

st = adcs_wheel_momentum(wm_input.wheels, wm_input.count, &h);
if (st != ADCS_OK) {
    wm_state.mode = WM_FAULT;
    wm_state.good = 0U;
    wm_output.mode = WM_FAULT;
    wm_output.good = 0U;
    return;
}

err = adcs_vec3_sub(&h, &wm_config.target);
norm = adcs_vec3_norm(&err);
energy = adcs_vec3_dot(&err, &err);

wm_output.momentum = h;
wm_output.error = err;
wm_output.error_norm = norm;
wm_output.error_energy = energy;

/* 状态迁移表 */
if (wm_state.mode == WM_ACTIVE) {
    if (norm <= wm_config.stop) {
        wm_state.good = wm_state.good + 1U;
        if (wm_state.good >= wm_config.required) {
            wm_state.mode = WM_COMPLETE;
        } else {
            wm_state.mode = WM_ACTIVE;
        }
    } else {
        wm_state.good = 0U;
        wm_state.mode = WM_ACTIVE;
    }
} else if (wm_state.mode == WM_COMPLETE) {
    if (norm < wm_config.restart) {
        /* preserve */
    } else {
        wm_state.mode = WM_ACTIVE;
        wm_state.good = 0U;
    }
} else {
    /* WM_FAULT 视为 invalid enabled cycle，保持 FAULT */
    wm_state.mode = WM_FAULT;
    wm_state.good = 0U;
}

wm_output.mode = wm_state.mode;
wm_output.good = wm_state.good;

